package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import static org.junit.jupiter.api.Assumptions.assumeTrue;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.jlinalg.genetics.MagmaTables;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaWorkflowCliTest {
    @TempDir Path dir;
    private int run(Map<String,Object> recipe,String name)throws Exception{Path file=dir.resolve(name+".json");Files.writeString(file,RegenieRuntime.json(recipe));return FumaToolsCli.run(new String[]{"--workflow-options-file",file.toString(),"--out",dir.resolve(name).toString()},new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream()));}
    private Map<?,?> manifest(String name)throws Exception{return AdmixtureInputs.decode(Files.readAllBytes(dir.resolve(name+"/manifest.json")));}
    private Map<?,?> stages(String name)throws Exception{return (Map<?,?>)manifest(name).get("stages");}
    private int code(String name,String stage)throws Exception{return ((Number)((Map<?,?>)stages(name).get(stage)).get("exit_code")).intValue();}
    private FumaWorkflowInputs.Data data(Path file)throws Exception{return FumaWorkflowInputs.read(file,new LinkedHashMap<>(),new FumaWorkflowInputs.Limits(10000000,100000));}
    private void magma(Map<String,Object> recipe,String home){Path resources=Path.of("src/test/resources/magma").toAbsolutePath();recipe.put("build","GRCh38");FumaWorkflowTestData.stage(recipe,"mapping").put("annotation-id","synthetic-GRCh38");FumaWorkflowTestData.stage(recipe,"gene_set").put("annotation-id","synthetic-GRCh38");recipe.put("magma_annotate",new LinkedHashMap<>(Map.of("method","annotate-native","genes",resources.resolve("genes.tsv").toString(),"snps",resources.resolve("snps.tsv").toString())));recipe.put("magma_gene",new LinkedHashMap<>(Map.of("home",home,"reference-panel",resources.resolve("reference").toString(),"ancestry","SYNTHETIC","input-mode","summary","pvalues",resources.resolve("gwas.tsv").toString(),"model","mean","seed","42")));recipe.put("magma_enrichment",new LinkedHashMap<>(Map.of("method","sets","home",home,"sets",resources.resolve("sets.annot").toString(),"seed","42")));}
    @Test void nativeLociMappingScoresAndGeneSetsUseStableAuditedStagePaths()throws Exception{var r=FumaWorkflowTestData.recipe(dir,true);assertEquals(0,run(r,"native"));assertEquals(5,stages("native").size());for(String id:new String[]{"loci","variant-preparation","mapping","gene-set-query","gene-set"})assertEquals(0,code("native",id));var genes=data(dir.resolve("native/mapping/genes.tsv"));assertEquals(2,genes.rows().size());assertEquals("0.123456789012345678901",genes.value(genes.rows().get(0),"score.pLI"));var tests=data(dir.resolve("native/gene-set/all-tests.tsv"));assertEquals(1.0/6,Double.parseDouble(tests.value(tests.rows().get(0),"p")),1e-15);assertEquals(List.of("G1","G2"),Files.readAllLines(dir.resolve("native/gene-set-query/query.txt")));assertTrue(Files.readString(dir.resolve("native/manifest.json")).contains(dir.resolve("native/mapping/genes.tsv").toString().replace("\\","\\\\")));}
    @Test void mappingCanStartFromExplicitCandidateResourcesWithoutLocusStage()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);assertEquals(0,run(r,"mapped"));assertEquals(3,stages("mapped").size());assertEquals(2,data(dir.resolve("mapped/mapping/genes.tsv")).rows().size());}
    @Test void resourceExtraRowsNeedAnExplicitAuditedExclusionChoice()throws Exception{var r=FumaWorkflowTestData.recipe(dir,true);Files.writeString(dir.resolve("variant-annotations.tsv"),Files.readString(dir.resolve("variant-annotations.tsv"))+"1:999999:A:G\t1\t999999\t5\t3\n");assertEquals(0,run(r,"extras"));assertTrue(Files.readString(dir.resolve("extras/variant-preparation/resource-disposition.tsv")).contains("excluded-outside-locus-candidates"));FumaWorkflowTestData.stage(r,"variant_resources").put("extra_rows","error");assertEquals(2,run(r,"strict-extras"));assertEquals(2,code("strict-extras","variant-preparation"));assertEquals(3,code("strict-extras","mapping"));}
    @Test void chromosomePositionMismatchDoesNotSilentlyReannotateSelectedVariant()throws Exception{var r=FumaWorkflowTestData.recipe(dir,true);String s=Files.readString(dir.resolve("variant-annotations.tsv"));Files.writeString(dir.resolve("variant-annotations.tsv"),s.replaceFirst("\\t100\\t","\t101\t"));assertEquals(2,run(r,"mismatch"));assertEquals(2,code("mismatch","variant-preparation"));assertFalse(Files.exists(dir.resolve("mismatch/mapping/genes.tsv")));}
    @Test void separateCandidateScoreSourceIsNeverReplacedByAnnotationScores()throws Exception{var r=FumaWorkflowTestData.recipe(dir,true);String scores=Files.readString(dir.resolve("variant-annotations.tsv")).replace("\t10\t2","\t99\t2");Files.writeString(dir.resolve("candidate-scores.tsv"),scores);var resources=FumaWorkflowTestData.stage(r,"variant_resources");resources.put("candidate_score_source","file");resources.put("candidate_score_file","candidate-scores.tsv");FumaWorkflowTestData.stage(r,"mapping").put("pos-cadd","20");assertEquals(0,run(r,"score-source"));var table=data(dir.resolve("score-source/variant-preparation/candidates.tsv"));assertTrue(table.rows().stream().allMatch(row->{try{return table.value(row,"CADD").equals("99");}catch(Exception e){throw new AssertionError(e);}}));assertTrue(Files.readString(dir.resolve("score-source/mapping/WARNINGS.md")).contains("DISTINCT SCORE SOURCES"));}
    @Test void emptyLociSkipOnlyDependentStagesWithNoFabricatedCandidates()throws Exception{var r=FumaWorkflowTestData.recipe(dir,true);var loci=FumaWorkflowTestData.stage(r,"loci");loci.put("lead-p","1e-300");loci.put("empty","retain");assertEquals(3,run(r,"empty"));assertEquals(0,code("empty","loci"));assertEquals(3,code("empty","variant-preparation"));assertEquals(3,code("empty","gene-set"));assertFalse(Files.exists(dir.resolve("empty/mapping/genes.tsv")));assertTrue(Files.readString(dir.resolve("empty/WARNINGS.md")).contains("Required action"));}
    @Test void missingMagmaRuntimeSkipsItsDependentBranchWhileNativeStagesComplete()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);magma(r,dir.resolve("absent-home").toString());assertEquals(3,run(r,"missing-magma"));assertEquals(0,code("missing-magma","mapping"));assertEquals(0,code("missing-magma","gene-set"));assertEquals(0,code("missing-magma","magma-annotation"));assertEquals(3,code("missing-magma","magma-gene"));assertEquals(3,code("missing-magma","magma-enrichment"));assertTrue(Files.readString(dir.resolve("missing-magma/magma-gene/WARNINGS.md")).contains("install_magma.py"));assertFalse(Files.exists(dir.resolve("missing-magma/magma-gene/results.tsv")));}
    @Test void mappingFailureDoesNotPreventIndependentNativeMagmaAnnotation()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);magma(r,dir.resolve("absent-home").toString());FumaWorkflowTestData.stage(r,"mapping").put("genes","absent.tsv");assertEquals(2,run(r,"mapping-failed"));assertEquals(2,code("mapping-failed","mapping"));assertEquals(3,code("mapping-failed","gene-set"));assertEquals(0,code("mapping-failed","magma-annotation"));}
    @Test void derivedQueriesCannotSwitchToTheGlobalSymbolNamespace()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);Files.writeString(dir.resolve("genes.tsv"),Files.readString(dir.resolve("genes.tsv")).replace("G2\tTWO\t","G2\tG1\t"));assertEquals(2,run(r,"namespace"));assertEquals(2,code("namespace","gene-set-query"));assertEquals(3,code("namespace","gene-set"));assertTrue(Files.readString(dir.resolve("namespace/gene-set-query/WARNINGS.md")).contains("global namespace"));}
    @Test void externalGeneSetQueriesRemainExplicitlyIndependent()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);r.remove("mapping");r.put("gene_set_query_policy","external");Files.writeString(dir.resolve("query.txt"),"G1\nG2\n");FumaWorkflowTestData.stage(r,"gene_set").put("query","query.txt");assertEquals(0,run(r,"external"));assertEquals(1,stages("external").size());}
    @Test void explicitBackgroundLeavingOneSupportedGeneSkipsTheTestAndRetainsPreflightAudit()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);var gs=FumaWorkflowTestData.stage(r,"gene_set");gs.remove("biotypes");gs.put("background","background.txt");Files.writeString(dir.resolve("background.txt"),"G1\nG3\nG4\n");assertEquals(3,run(r,"background-subset"));assertEquals(3,code("background-subset","gene-set-query"));assertTrue(Files.exists(dir.resolve("background-subset/gene-set-query/partial/query-preflight-id-mapping.tsv")));assertFalse(Files.exists(dir.resolve("background-subset/gene-set/all-tests.tsv")));}
    @Test void invalidSchemaAndUnknownRootFieldsFailBeforeCreatingOutputs()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);r.put("schema_version","1");assertEquals(2,run(r,"bad-schema"));assertFalse(Files.exists(dir.resolve("bad-schema")));r.put("schema_version",1);r.put("arbitrary_command","ignored");assertEquals(2,run(r,"unknown"));assertFalse(Files.exists(dir.resolve("unknown")));}
    @Test void wrongTypesReservedOutputAndBuildMismatchAreRejected()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);FumaWorkflowTestData.stage(r,"mapping").put("out","override");assertEquals(2,run(r,"reserved"));FumaWorkflowTestData.stage(r,"mapping").remove("out");magma(r,"absent");FumaWorkflowTestData.stage(r,"magma_gene").put("build","DIFFERENT");assertEquals(2,run(r,"build"));assertFalse(Files.exists(dir.resolve("build")));}
    @Test void existingOutputDirectoryIsNeverOverwritten()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);Files.createDirectory(dir.resolve("existing"));Files.writeString(dir.resolve("existing/sentinel"),"keep");assertEquals(2,run(r,"existing"));assertEquals("keep",Files.readString(dir.resolve("existing/sentinel")));}
    @Test void relativeResourcePathsResolveAgainstTheRecipeDirectory()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);assertEquals(0,run(r,"relative"));var source=(Map<?,?>)manifest("relative").get("source_and_stage_sha256");assertTrue(source.containsKey(dir.resolve("genes.tsv").toString()));}
    @Test void rootOutputHashesCoverTheRetainedStageResultsAndLogs()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);assertEquals(0,run(r,"hashes"));var outputs=(Map<?,?>)manifest("hashes").get("output_sha256");for(var entry:outputs.entrySet())assertEquals(entry.getValue(),FollowupSupport.hash(dir.resolve("hashes").resolve(entry.getKey().toString())));assertTrue(Files.readString(dir.resolve("hashes/analysis-status.json")).contains("completed-with-review-warnings"));}
    @Test void journalMarksEverySelectedStageAndStablePathsRemainReusable()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);String home=System.getenv("JLINALG_MAGMA_HOME");assumeTrue(home!=null);magma(r,home);assertEquals(0,run(r,"full"));assertEquals(6,stages("full").size());Path resources=Path.of("src/test/resources/magma").toAbsolutePath();var expected=MagmaTables.table(resources.resolve("summary-mean.genes.out.txt"));var actual=MagmaTables.table(dir.resolve("full/magma-gene/results.tsv"));assertEquals(expected.columns(),actual.columns());assertEquals(expected.rows(),actual.rows());var bytes=new ByteArrayOutputStream();assertEquals(0,MagmaToolsCli.run(new String[]{"--method","properties","--home",home,"--build","GRCh38","--gene-bundle",dir.resolve("full/magma-gene").toString(),"--properties",resources.resolve("properties.tsv").toString(),"--property-direction","positive","--seed","42","--out",dir.resolve("reused-gene-bundle").toString()},new PrintStream(bytes),new PrintStream(bytes)),bytes.toString());}
    @Test void annotationClippingCannotOverrideTheGeneratedCandidateOrAnnotationPaths()throws Exception{var r=FumaWorkflowTestData.recipe(dir,true);FumaWorkflowTestData.stage(r,"mapping").put("candidates","somewhere.tsv");assertEquals(2,run(r,"conflict"));assertFalse(Files.exists(dir.resolve("conflict")));}
    @Test void declarationOnlyGenesDoNotBecomeGeneSetQueries()throws Exception{var r=FumaWorkflowTestData.recipe(dir,false);var map=FumaWorkflowTestData.stage(r,"mapping");map.put("positional","none");map.remove("window-bp");for(String k:List.copyOf(map.keySet()))if(k.startsWith("pos-"))map.remove(k);Files.writeString(dir.resolve("ci.tsv"),"interaction_id\tregion1\tregion2\tgenes\trsIDs\ttissue\nI1\t1:100-100\t1:900-3100\tG2\trs2\tA\nI2\t1:1000-1000\t1:1-200\tG1\trs1\tB\n");Files.writeString(dir.resolve("promoters.tsv"),"region2\tgenes\n1:900-3100\tG2\n");map.putAll(Map.of("chromatin","supplied","interactions","ci.tsv","ci-membership","source-global","ci-coordinates","source-closed","ci-enhancers","none","ci-promoters","promoters.tsv","ci-cadd","0","ci-rdb","none","ci-states","none","ci-binary","none"));assertEquals(3,run(r,"declarations"));assertEquals(0,code("declarations","mapping"));assertEquals(3,code("declarations","gene-set-query"));assertTrue(Files.readString(dir.resolve("declarations/gene-set-query/partial/query-disposition.tsv")).contains("excluded-declaration-only"));assertFalse(Files.exists(dir.resolve("declarations/gene-set/GS.txt")));}
}
